contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address log) public payable {
        c.SetLogFile(log); if (__ESBMC_reverted()) return;
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetLogFile(address(0x1234)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.MinSum() == beforeMinSum);
    }

    receive() external payable {}
}

